import * as d3 from 'd3';
import {
  drawArrow,
  drawCodeAnnotation,
  drawComponentLink,
  drawExplanation,
  drawLabel,
  drawMatrixBlock,
  Sel,
} from '../primitives';
import { StepInfo } from './index';
import { ComponentDef } from '../../components/types';
import { ComputationGraph } from '../../graph/types';

type Gsel = d3.Selection<SVGGElement, unknown, null, undefined>;

const W = 1100;
const CX = W / 2;

const COLORS = {
  latent: { fill: '#ede7f6', stroke: '#4527a0' },
  time: { fill: '#fff3e0', stroke: '#e65100' },
  model: { fill: '#e3f2fd', stroke: '#1976d2' },
  schedule: { fill: '#e0f2f1', stroke: '#00897b' },
  update: { fill: '#fce4ec', stroke: '#c62828' },
  noise: { fill: '#f3e5f5', stroke: '#7b1fa2' },
  out: { fill: '#e8f5e9', stroke: '#2e7d32' },
  weight: { fill: '#f1f8e8', stroke: '#64748b' },
  muted: 'var(--text-muted)' as string,
};

const BOX_H = 72;
const MAT_H = 80;
const VEC_H = 36;
const SEQ_W = 180;
const STEP_GAP = 120;
const BOX_TO_ROW = 90;
const ROW_GAP = 100;
const SHAPE_GAP = 44;

// ═══════════════════════════════════════════════════════════════════════════════
// Helpers
// ═══════════════════════════════════════════════════════════════════════════════

interface SchedulerStep extends StepInfo {}
type SchedulerType = 'ddpm' | 'ddim' | 'euler' | 'dpm++';

function lbl(
  g: Gsel, x: number, y: number, text: string,
  opts: { size?: number; weight?: string; color?: string; anchor?: 'start' | 'middle' | 'end'; font?: string } = {}
): void {
  drawLabel(g as Sel, x, y, text, opts);
}

function arrowDown(g: Gsel, x: number, y1: number, y2: number, color = '#94a3b8'): void {
  drawArrow(g as Sel, x, y1, x, y2, { color });
}

function startGroup(g: Gsel, cls: string, step: number): Gsel {
  return g.append('g').attr('class', `step-node ${cls}`).attr('data-step', String(step));
}

function stepHeader(
  g: Gsel, cx: number, y: number, sn: number, title: string, formula: string,
  fill: string, stroke: string, width = 940
): number {
  const w = width;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', BOX_H)
    .attr('rx', 8).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  g.append('circle').attr('cx', cx - w / 2 + 26).attr('cy', y + BOX_H / 2)
    .attr('r', 15).attr('fill', stroke);
  lbl(g, cx - w / 2 + 26, y + BOX_H / 2 + 1, String(sn), { size: 13, weight: '700', color: '#fff' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 - 6, title, { size: 14, weight: '600', color: 'var(--text)', anchor: 'start' });
  lbl(g, cx - w / 2 + 52, y + BOX_H / 2 + 12, formula, { size: 10, color: 'var(--text-muted)', font: 'monospace', anchor: 'start' });
  return y + BOX_H;
}

function shapeEq(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  const w = Math.max(text.length * 6.5 + 32, 220);
  const h = 30;
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 4).attr('fill', 'var(--surface)').attr('stroke', color).attr('stroke-width', 0.5).attr('opacity', 0.9);
  lbl(g, cx, cy + 1, text, { size: 9, color, font: 'monospace' });
}

function seqMatrix(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = SEQ_W, h = MAT_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke,
    cols: 8, rows: 5, dimTop: 'P', dimRight: 'D',
  });
}

function smallVec(
  g: Gsel, cx: number, cy: number, label: string, sub: string,
  fill: string, stroke: string, w = 110, h = VEC_H
): void {
  drawMatrixBlock(g as Sel, cx - w / 2, cy - h / 2, {
    width: w, height: h, label, sublabel: sub, fill, stroke, cols: 5, rows: 1,
  });
}

function smallOp(g: Gsel, cx: number, cy: number, text: string, color: string): void {
  g.append('circle').attr('cx', cx).attr('cy', cy).attr('r', 14)
    .attr('fill', '#fff').attr('stroke', color).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '700', color });
}

function badgeRect(g: Gsel, cx: number, cy: number, text: string, fill: string, stroke: string, w = 120, h = 32): void {
  g.append('rect').attr('x', cx - w / 2).attr('y', cy - h / 2).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', fill).attr('stroke', stroke).attr('stroke-width', 1.5);
  lbl(g, cx, cy + 1, text, { size: 10, weight: '600', color: stroke });
}

function paramSummary(g: Gsel, cx: number, y: number, items: string[]): number {
  const w = W - 160;
  const h = 36;
  g.append('rect').attr('x', cx - w / 2).attr('y', y).attr('width', w).attr('height', h)
    .attr('rx', 6).attr('fill', 'var(--surface)').attr('stroke', 'var(--border)').attr('stroke-width', 0.5);
  const segW = w / items.length;
  items.forEach((item, i) => {
    lbl(g, cx - w / 2 + segW * (i + 0.5), y + h / 2 + 1, item, { size: 10, color: COLORS.muted, font: 'monospace' });
  });
  return y + h;
}

function makeStep(
  id: number, sl: string, l: string, f: string, ex: string,
  sg: string, c: string, fl: string, cl?: string[]
): SchedulerStep {
  return { id, label: l, shortLabel: sl, formula: f, explanation: ex,
    code: { title: l, lines: cl || [`# ${f}`] }, svgGroup: sg, color: c, fill: fl };
}

// ═══════════════════════════════════════════════════════════════════════════════
// Per-scheduler update-step renderers
// ═══════════════════════════════════════════════════════════════════════════════

function renderDdpmUpdate(
  g: Gsel, cx: number, y: number, nPatches: number, dModel: number
): number {
  const rowY = y + BOX_TO_ROW;

  // Row 1: posterior mean  μ_θ = (z_t - β_t/√(1-ᾱ_t)·ε_θ) / √α_t
  seqMatrix(g, cx - 420, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 150, MAT_H);
  smallOp(g, cx - 310, rowY, '-', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 420 + 75 + 4, rowY, cx - 310 - 14, rowY, { color: COLORS.update.stroke });

  smallVec(g, cx - 210, rowY, 'β_t/√(1-ᾱ_t)', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 130, VEC_H);
  smallOp(g, cx - 150, rowY, '×', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 210 + 65 + 4, rowY, cx - 150 - 14, rowY, { color: COLORS.schedule.stroke });

  seqMatrix(g, cx - 30, rowY, 'ε_θ', `[${nPatches}, ${dModel}]`, COLORS.model.fill, COLORS.model.stroke, 140, MAT_H);
  drawArrow(g as Sel, cx - 30 - 70 - 4, rowY, cx - 150 + 14, rowY, { color: COLORS.model.stroke });

  smallOp(g, cx + 90, rowY, '/', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 310 + 14, rowY, cx + 90 - 14, rowY, { color: COLORS.update.stroke });

  smallVec(g, cx + 170, rowY, '√α_t', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  drawArrow(g as Sel, cx + 170 - 40 - 4, rowY, cx + 90 + 14, rowY, { color: COLORS.schedule.stroke });

  seqMatrix(g, cx + 320, rowY, 'μ_θ', `[${nPatches}, ${dModel}]`, COLORS.update.fill, COLORS.update.stroke, 150, MAT_H);
  drawArrow(g as Sel, cx + 90 + 14, rowY, cx + 320 - 75 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `μ_θ = (z_t - β_t/√(1-ᾱ_t) · ε_θ) / √α_t  →  [${nPatches}, ${dModel}]`, COLORS.update.stroke);

  // Row 2: add stochastic noise  z_{t-1} = μ_θ + √β_t·ε
  const row2Y = rowY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  seqMatrix(g, cx - 220, row2Y, 'μ_θ', `[${nPatches}, ${dModel}]`, COLORS.update.fill, COLORS.update.stroke, 150, MAT_H);
  smallOp(g, cx - 80, row2Y, '+', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 220 + 75 + 4, row2Y, cx - 80 - 14, row2Y, { color: COLORS.update.stroke });

  smallVec(g, cx + 40, row2Y, '√β_t·ε', `[D]`, COLORS.noise.fill, COLORS.noise.stroke, 110, VEC_H);
  lbl(g, cx + 40, row2Y - 28, 'ε ~ N(0,I)', { size: 8, color: COLORS.noise.stroke, weight: '600' });
  drawArrow(g as Sel, cx + 40 - 55 - 4, row2Y, cx - 80 + 14, row2Y, { color: COLORS.noise.stroke });

  seqMatrix(g, cx + 180, row2Y, 'z_{t-1}', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 150, MAT_H);
  drawArrow(g as Sel, cx - 80 + 14, row2Y, cx + 180 - 75 - 4, row2Y, { color: COLORS.update.stroke });

  shapeEq(g, cx, row2Y + MAT_H / 2 + 24,
    `z_{t-1} = μ_θ + √β_t · ε  →  [${nPatches}, ${dModel}]`, COLORS.update.stroke);

  return row2Y + MAT_H / 2 + 24 + SHAPE_GAP;
}

function renderDdimUpdate(
  g: Gsel, cx: number, y: number, nPatches: number, dModel: number
): number {
  const rowY = y + BOX_TO_ROW;

  // Predict x_0
  seqMatrix(g, cx - 320, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 150, MAT_H);
  smallOp(g, cx - 210, rowY, '-', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 320 + 75 + 4, rowY, cx - 210 - 14, rowY, { color: COLORS.update.stroke });

  smallVec(g, cx - 110, rowY, '√(1-ᾱ_t)', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 120, VEC_H);
  smallOp(g, cx - 60, rowY, '×', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 110 + 60 + 4, rowY, cx - 60 - 14, rowY, { color: COLORS.schedule.stroke });

  seqMatrix(g, cx + 40, rowY, 'ε_θ', `[${nPatches}, ${dModel}]`, COLORS.model.fill, COLORS.model.stroke, 140, MAT_H);
  drawArrow(g as Sel, cx + 40 - 70 - 4, rowY, cx - 60 + 14, rowY, { color: COLORS.model.stroke });

  smallOp(g, cx + 130, rowY, '/', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 60 + 14, rowY, cx + 130 - 14, rowY, { color: COLORS.update.stroke });

  smallVec(g, cx + 200, rowY, '√ᾱ_t', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 90, VEC_H);
  drawArrow(g as Sel, cx + 200 - 45 - 4, rowY, cx + 130 + 14, rowY, { color: COLORS.schedule.stroke });

  seqMatrix(g, cx + 340, rowY, 'x_0_pred', `[${nPatches}, ${dModel}]`, COLORS.update.fill, COLORS.update.stroke, 150, MAT_H);
  drawArrow(g as Sel, cx + 130 + 14, rowY, cx + 340 - 75 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `x_0_pred = (z_t - √(1-ᾱ_t)·ε_θ) / √ᾱ_t  →  [${nPatches}, ${dModel}]`, COLORS.update.stroke);

  // Reconstruct z_{t-1}
  const row2Y = rowY + MAT_H / 2 + 24 + SHAPE_GAP + ROW_GAP;
  seqMatrix(g, cx - 280, row2Y, 'x_0_pred', `[${nPatches}, ${dModel}]`, COLORS.update.fill, COLORS.update.stroke, 150, MAT_H);
  smallOp(g, cx - 170, row2Y, '×', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 280 + 75 + 4, row2Y, cx - 170 - 14, row2Y, { color: COLORS.update.stroke });

  smallVec(g, cx - 80, row2Y, '√ᾱ_{t-1}', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 120, VEC_H);
  drawArrow(g as Sel, cx - 80 - 60 - 4, row2Y, cx - 170 + 14, row2Y, { color: COLORS.schedule.stroke });

  smallOp(g, cx + 20, row2Y, '+', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 170 + 14, row2Y, cx + 20 - 14, row2Y, { color: COLORS.update.stroke });

  seqMatrix(g, cx + 130, row2Y, 'ε_θ', `[${nPatches}, ${dModel}]`, COLORS.model.fill, COLORS.model.stroke, 120, MAT_H);
  smallOp(g, cx + 210, row2Y, '×', COLORS.update.stroke);
  drawArrow(g as Sel, cx + 130 + 60 + 4, row2Y, cx + 210 - 14, row2Y, { color: COLORS.model.stroke });

  smallVec(g, cx + 300, row2Y, '√(1-ᾱ_{t-1})', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 130, VEC_H);
  drawArrow(g as Sel, cx + 300 - 65 - 4, row2Y, cx + 210 + 14, row2Y, { color: COLORS.schedule.stroke });

  drawArrow(g as Sel, cx + 210 + 14, row2Y, cx + 20 + 14, row2Y, { color: COLORS.update.stroke });

  seqMatrix(g, cx + 380, row2Y, 'z_{t-1}', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 140, MAT_H);
  drawArrow(g as Sel, cx + 20 + 14, row2Y, cx + 380 - 70 - 4, row2Y, { color: COLORS.update.stroke });

  shapeEq(g, cx, row2Y + MAT_H / 2 + 24,
    `z_{t-1} = √ᾱ_{t-1}·x_0_pred + √(1-ᾱ_{t-1})·ε_θ  →  [${nPatches}, ${dModel}]`, COLORS.update.stroke);

  return row2Y + MAT_H / 2 + 24 + SHAPE_GAP;
}

function renderEulerUpdate(
  g: Gsel, cx: number, y: number, nPatches: number, dModel: number
): number {
  const rowY = y + BOX_TO_ROW;

  seqMatrix(g, cx - 260, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 160, MAT_H);
  smallOp(g, cx - 120, rowY, '-', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 260 + 80 + 4, rowY, cx - 120 - 14, rowY, { color: COLORS.update.stroke });

  seqMatrix(g, cx + 20, rowY, 'ε_θ', `[${nPatches}, ${dModel}]`, COLORS.model.fill, COLORS.model.stroke, 140, MAT_H);
  smallOp(g, cx + 100, rowY, '×', COLORS.update.stroke);
  drawArrow(g as Sel, cx + 20 + 70 + 4, rowY, cx + 100 - 14, rowY, { color: COLORS.model.stroke });

  smallVec(g, cx + 210, rowY, 'σ_t', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  drawArrow(g as Sel, cx + 210 - 40 - 4, rowY, cx + 100 + 14, rowY, { color: COLORS.schedule.stroke });

  drawArrow(g as Sel, cx + 100 + 14, rowY, cx - 120 + 14, rowY, { color: COLORS.update.stroke });

  seqMatrix(g, cx + 340, rowY, 'z_{t-1}', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 160, MAT_H);
  drawArrow(g as Sel, cx - 120 + 14, rowY, cx + 340 - 80 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `z_{t-1} = z_t - σ_t · ε_θ  →  [${nPatches}, ${dModel}]`, COLORS.update.stroke);

  return rowY + MAT_H / 2 + 24 + SHAPE_GAP;
}

function renderDpmppUpdate(
  g: Gsel, cx: number, y: number, nPatches: number, dModel: number
): number {
  const rowY = y + BOX_TO_ROW;

  seqMatrix(g, cx - 400, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 150, MAT_H);
  smallOp(g, cx - 30, rowY, '+', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 400 + 75 + 4, rowY, cx - 70, rowY, { color: COLORS.update.stroke });

  seqMatrix(g, cx - 190, rowY, 'ε_t', `[${nPatches}, ${dModel}]`, COLORS.model.fill, COLORS.model.stroke, 130, MAT_H);
  smallOp(g, cx - 110, rowY, '×', COLORS.update.stroke);
  drawArrow(g as Sel, cx - 190 + 65 + 4, rowY, cx - 110 - 14, rowY, { color: COLORS.model.stroke });

  smallVec(g, cx - 50, rowY, 'γ_1', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  drawArrow(g as Sel, cx - 50 - 40 - 4, rowY, cx - 110 + 14, rowY, { color: COLORS.schedule.stroke });

  drawArrow(g as Sel, cx - 110 + 14, rowY, cx - 68, rowY, { color: COLORS.update.stroke });

  seqMatrix(g, cx + 90, rowY, 'ε_{t-1}', `[${nPatches}, ${dModel}]`, COLORS.noise.fill, COLORS.noise.stroke, 130, MAT_H);
  smallOp(g, cx + 170, rowY, '×', COLORS.update.stroke);
  drawArrow(g as Sel, cx + 90 + 65 + 4, rowY, cx + 170 - 14, rowY, { color: COLORS.noise.stroke });

  smallVec(g, cx + 250, rowY, 'γ_2', `[D]`, COLORS.schedule.fill, COLORS.schedule.stroke, 80, VEC_H);
  drawArrow(g as Sel, cx + 250 - 40 - 4, rowY, cx + 170 + 14, rowY, { color: COLORS.schedule.stroke });

  drawArrow(g as Sel, cx + 170 + 14, rowY, cx + 8, rowY, { color: COLORS.update.stroke });

  seqMatrix(g, cx + 350, rowY, 'z_{t-1}', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 150, MAT_H);
  drawArrow(g as Sel, cx + 8, rowY, cx + 350 - 75 - 4, rowY, { color: COLORS.update.stroke });

  shapeEq(g, cx, rowY + MAT_H / 2 + 24,
    `z_{t-1} = z_t + γ_1·ε_t + γ_2·ε_{t-1}  →  [${nPatches}, ${dModel}]`, COLORS.update.stroke);

  return rowY + MAT_H / 2 + 24 + SHAPE_GAP;
}

// ═══════════════════════════════════════════════════════════════════════════════
// Main renderer
// ═══════════════════════════════════════════════════════════════════════════════

export function renderDiffusionSchedulerDetailed(
  g: Gsel,
  params: Record<string, number | string>,
  _meta: ComponentDef,
  _graph: ComputationGraph
): { width: number; height: number; steps: StepInfo[] } {
  const nPatches = Number(params.n_patches) || 256;
  const dModel = Number(params.d_model) || 768;
  const steps = Number(params.steps) || 50;
  const scheduler = String(params.scheduler || 'ddpm') as SchedulerType;

  const schedulerLabel: Record<SchedulerType, string> = {
    ddpm: 'DDPM (stochastic)',
    ddim: 'DDIM (deterministic)',
    euler: 'Euler (flow-based)',
    'dpm++': 'DPM++ 2M (multi-step)',
  };

  const stepsMeta: SchedulerStep[] = [];
  let stepId = 0;
  let y = 10;

  // Title
  lbl(g, CX, y + 14, 'Diffusion Scheduler', { size: 18, weight: '700', color: 'var(--text)' });
  y += 36;
  lbl(g, CX, y + 8, `${schedulerLabel[scheduler]} — iteratively denoise latents using a noise schedule`, { size: 10, color: 'var(--text-muted)' });
  y += 30;

  y = paramSummary(g, CX, y, [
    `patches: ${nPatches}`, `d_model: ${dModel}`, `steps: ${steps}`, `scheduler: ${scheduler.toUpperCase()}`,
  ]);
  y += 32;

  // ── Step 1: Input ────────────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-input', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Input: Noisy Latent & Timestep',
      `z_t: [${nPatches}, ${dModel}]    t: [1]`,
      COLORS.latent.fill, COLORS.latent.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.latent.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    seqMatrix(gs, CX - 200, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 170, MAT_H);
    lbl(gs, CX - 200, rowY - MAT_H / 2 - 14, 'Noisy Latent', { size: 10, color: COLORS.latent.stroke, weight: '600' });

    const tW = 110;
    drawMatrixBlock(gs as Sel, CX + 200 - tW / 2, rowY - 18, {
      width: tW, height: 36, label: 't', sublabel: '[1]',
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 3, rows: 1,
    });
    lbl(gs, CX + 200, rowY - 32, 'Timestep', { size: 10, color: COLORS.time.stroke, weight: '600' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 22,
      `z_t is the noisy latent at timestep t (t=${steps} ... 0)`, COLORS.latent.stroke);

    stepsMeta.push(makeStep(stepId, 'Input', 'Input: Noisy Latent & Timestep',
      `z_t [${nPatches}, ${dModel}], t [1]`,
      'The diffusion sampling loop starts from a noisy latent z_t and a scalar timestep t.',
      'step-input', COLORS.latent.stroke, COLORS.latent.fill,
      [`z_t = noisy latent at timestep t   # [${nPatches}, ${dModel}]`,
       `t   = current timestep scalar        # e.g. ${steps} -> 0`]));
    y = rowY + MAT_H / 2 + 22 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 2: Predict Noise ────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-predict', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Predict Noise',
      `ε_θ = DiT(z_t, t)  →  [${nPatches}, ${dModel}]`,
      COLORS.model.fill, COLORS.model.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.latent.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    seqMatrix(gs, CX - 260, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 160, MAT_H);

    const tW = 80;
    drawMatrixBlock(gs as Sel, CX - 150 - tW / 2, rowY - 16, {
      width: tW, height: 32, label: 't', sublabel: '[1]',
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 3, rows: 1,
    });

    badgeRect(gs, CX - 30, rowY, 'DiT', COLORS.model.fill, COLORS.model.stroke, 90, 36);
    drawArrow(g as Sel, CX - 260 + 80 + 4, rowY, CX - 30 - 45 - 4, rowY, { color: COLORS.latent.stroke });
    drawArrow(g as Sel, CX - 150 + tW / 2 + 4, rowY, CX - 30 - 45 - 4, rowY, { color: COLORS.time.stroke });

    seqMatrix(gs, CX + 140, rowY, 'ε_θ', `[${nPatches}, ${dModel}]`, COLORS.model.fill, COLORS.model.stroke, 170, MAT_H);
    drawArrow(g as Sel, CX - 30 + 45 + 4, rowY, CX + 140 - 85 - 4, rowY, { color: COLORS.model.stroke });
    lbl(gs, CX + 140, rowY - MAT_H / 2 - 14, 'Predicted Noise', { size: 10, color: COLORS.model.stroke, weight: '600' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 24,
      `ε_θ = DiT(z_t, t)  →  [${nPatches}, ${dModel}]`, COLORS.model.stroke);

    stepsMeta.push(makeStep(stepId, 'Predict', 'Predict Noise',
      `ε_θ = DiT(z_t, t)`,
      'The diffusion model predicts the noise that was added to the clean latent.',
      'step-predict', COLORS.model.stroke, COLORS.model.fill,
      [`# Noise prediction network (e.g. DiT)`,
       `eps_pred = model(z_t, t)   # [${nPatches}, ${dModel}]`]));
    y = rowY + MAT_H / 2 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 3: Schedule Coefficients ────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-schedule', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Schedule Coefficients',
      `lookup α_t, ᾱ_t, β_t, σ_t from ${scheduler.toUpperCase()} schedule`,
      COLORS.schedule.fill, COLORS.schedule.stroke);

    arrowDown(gs, CX + 160, y, hBottom, COLORS.time.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    const tW = 80;
    drawMatrixBlock(gs as Sel, CX - 220 - tW / 2, rowY - 16, {
      width: tW, height: 32, label: 't', sublabel: '[1]',
      fill: COLORS.time.fill, stroke: COLORS.time.stroke, cols: 3, rows: 1,
    });

    badgeRect(gs, CX - 60, rowY, 'Schedule', COLORS.schedule.fill, COLORS.schedule.stroke, 130, 36);
    drawArrow(g as Sel, CX - 220 + tW / 2 + 4, rowY, CX - 60 - 65 - 4, rowY, { color: COLORS.time.stroke });

    const coeffW = 320;
    const coeffH = 44;
    drawMatrixBlock(gs as Sel, CX + 120 - coeffW / 2, rowY - coeffH / 2, {
      width: coeffW, height: coeffH, label: 'coeffs', sublabel: `[α_t, ᾱ_t, β_t, σ_t]`,
      fill: COLORS.schedule.fill, stroke: COLORS.schedule.stroke, cols: 4, rows: 1,
    });
    drawArrow(g as Sel, CX - 60 + 65 + 4, rowY, CX + 120 - coeffW / 2 - 4, rowY, { color: COLORS.schedule.stroke });

    shapeEq(gs, CX, rowY + coeffH / 2 + 24,
      `β_t = 1 - α_t ;  ᾱ_t = ∏_{i=1}^{t} α_i ;  σ_t = √β_t`, COLORS.schedule.stroke);

    stepsMeta.push(makeStep(stepId, 'Schedule', 'Schedule Coefficients',
      `lookup α_t, ᾱ_t, β_t, σ_t`,
      'The scheduler maps timestep t to coefficients that control how much noise is removed and how much randomness is injected.',
      'step-schedule', COLORS.schedule.stroke, COLORS.schedule.fill,
      [`# Coefficient lookup from precomputed schedule`,
       `alpha_t, alpha_bar_t, beta_t, sigma_t = schedule[t]`]));
    y = rowY + coeffH / 2 + 24 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 4: Update Rule (per scheduler) ──────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-update', stepId);
    const title = scheduler === 'ddpm' ? 'DDPM Update (Stochastic)' :
                  scheduler === 'ddim' ? 'DDIM Update (Deterministic)' :
                  scheduler === 'euler' ? 'Euler Update (Flow-based)' :
                  'DPM++ 2M Update (Multi-step)';
    const formula = scheduler === 'ddpm' ? `z_{t-1} = μ_θ + √β_t·ε ; μ_θ = (z_t - β_t/√(1-ᾱ_t)·ε_θ)/√α_t` :
                    scheduler === 'ddim' ? `z_{t-1} = √ᾱ_{t-1}·x_0 + √(1-ᾱ_{t-1})·ε_θ` :
                    scheduler === 'euler' ? `z_{t-1} = z_t - σ_t·ε_θ` :
                    `z_{t-1} = z_t + γ_1·ε_t + γ_2·ε_{t-1}`;
    const hBottom = stepHeader(gs, CX, y, stepId, title, formula, COLORS.update.fill, COLORS.update.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.model.stroke);

    let nextY: number;
    switch (scheduler) {
      case 'ddim': nextY = renderDdimUpdate(gs, CX, hBottom, nPatches, dModel); break;
      case 'euler': nextY = renderEulerUpdate(gs, CX, hBottom, nPatches, dModel); break;
      case 'dpm++': nextY = renderDpmppUpdate(gs, CX, hBottom, nPatches, dModel); break;
      default: nextY = renderDdpmUpdate(gs, CX, hBottom, nPatches, dModel); break;
    }

    const explanation = scheduler === 'ddpm'
      ? 'DDPM computes the posterior mean μ_θ from z_t and the predicted noise, then samples z_{t-1} by adding Gaussian noise with variance β_t.'
      : scheduler === 'ddim'
      ? 'DDIM is deterministic: it reconstructs z_{t-1} from the predicted x_0 and the predicted noise direction, without sampling extra noise.'
      : scheduler === 'euler'
      ? 'Euler takes a simple first-order step along the predicted noise direction, scaled by the schedule sigma.'
      : 'DPM++ is a higher-order solver that combines the current and previous noise estimates for a more accurate update.';

    const codeLines = scheduler === 'ddpm'
      ? [`mu = (z_t - beta_t/sqrt(1-alpha_bar_t)*eps_pred) / sqrt(alpha_t)`,
         `z_tminus1 = mu + sqrt(beta_t)*randn_like(z_t)`]
      : scheduler === 'ddim'
      ? [`x0_pred = (z_t - sqrt(1-alpha_bar_t)*eps_pred) / sqrt(alpha_bar_t)`,
         `z_tminus1 = sqrt(alpha_bar_t_1)*x0_pred + sqrt(1-alpha_bar_t_1)*eps_pred`]
      : scheduler === 'euler'
      ? [`z_tminus1 = z_t - sigma_t * eps_pred`]
      : [`z_tminus1 = z_t + gamma_1*eps_t + gamma_2*eps_t_1`];

    stepsMeta.push(makeStep(stepId, 'Update', title, formula, explanation, 'step-update',
      COLORS.update.stroke, COLORS.update.fill, codeLines));
    y = nextY + STEP_GAP;
  }

  // ── Step 5: Iteration Loop ───────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-loop', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Iteration Loop',
      `repeat steps 2-4 for t = ${steps}, ${Math.max(1, steps - 1)}, ..., 0`,
      COLORS.schedule.fill, COLORS.schedule.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.update.stroke);

    const rowY = hBottom + BOX_TO_ROW;

    // Loop body visual: z_t -> [predict -> schedule -> update] -> z_{t-1}
    seqMatrix(gs, CX - 360, rowY, 'z_t', `[${nPatches}, ${dModel}]`, COLORS.latent.fill, COLORS.latent.stroke, 140, MAT_H);
    badgeRect(gs, CX - 220, rowY, 'predict', COLORS.model.fill, COLORS.model.stroke, 100, 34);
    drawArrow(g as Sel, CX - 360 + 70 + 4, rowY, CX - 220 - 50 - 4, rowY, { color: COLORS.latent.stroke });

    badgeRect(gs, CX - 80, rowY, 'schedule', COLORS.schedule.fill, COLORS.schedule.stroke, 110, 34);
    drawArrow(g as Sel, CX - 220 + 50 + 4, rowY, CX - 80 - 55 - 4, rowY, { color: COLORS.model.stroke });

    badgeRect(gs, CX + 60, rowY, 'update', COLORS.update.fill, COLORS.update.stroke, 90, 34);
    drawArrow(g as Sel, CX - 80 + 55 + 4, rowY, CX + 60 - 45 - 4, rowY, { color: COLORS.schedule.stroke });

    seqMatrix(gs, CX + 230, rowY, 'z_{t-1}', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 150, MAT_H);
    drawArrow(g as Sel, CX + 60 + 45 + 4, rowY, CX + 230 - 75 - 4, rowY, { color: COLORS.update.stroke });

    // Feedback arrow (curves below the loop row, from z_{t-1} back to z_t)
    const feedbackD = `M ${CX + 230} ${rowY + MAT_H / 2 + 4} C ${CX + 230} ${rowY + 140}, ${CX - 360} ${rowY + 140}, ${CX - 360} ${rowY + MAT_H / 2 + 4}`;
    gs.append('path')
      .attr('d', feedbackD)
      .attr('fill', 'none')
      .attr('stroke', COLORS.update.stroke)
      .attr('stroke-width', 1.5)
      .attr('stroke-dasharray', '6,4')
      .attr('marker-end', 'url(#arrowhead-loop)');

    // Marker for loop arrow
    g.append('defs').append('marker')
      .attr('id', 'arrowhead-loop')
      .attr('viewBox', '0 -5 10 10')
      .attr('refX', 8)
      .attr('refY', 0)
      .attr('markerWidth', 6)
      .attr('markerHeight', 6)
      .attr('orient', 'auto')
      .append('path')
      .attr('d', 'M0,-5L10,0L0,5')
      .attr('fill', COLORS.update.stroke);

    lbl(gs, CX - 65, rowY + MAT_H / 2 + 86, `repeat ${steps} times   (t → t-1)`, {
      size: 10, color: COLORS.update.stroke, weight: '600', anchor: 'middle'
    });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 110,
      `sampling loop: z_T (pure noise) → z_0 (clean latent) in ${steps} steps`, COLORS.schedule.stroke);

    stepsMeta.push(makeStep(stepId, 'Loop', 'Iteration Loop',
      `for t = ${steps} ... 0: z_{t-1} = update(z_t, ε_θ, schedule[t])`,
      'The update is repeated for every timestep, gradually converting random noise into a clean latent image.',
      'step-loop', COLORS.schedule.stroke, COLORS.schedule.fill,
      [`for t in reversed(range(${steps})):`,
       `    eps = model(z_t, t)`,
       `    z_t = scheduler_step(z_t, eps, t)`]));
    y = rowY + MAT_H / 2 + 110 + SHAPE_GAP + STEP_GAP;
  }

  // ── Step 6: Output ───────────────────────────────────────────────────────
  stepId++;
  {
    const gs = startGroup(g, 'step-output', stepId);
    const hBottom = stepHeader(gs, CX, y, stepId, 'Output: Denoised Latent',
      `z_0: [${nPatches}, ${dModel}]`,
      COLORS.out.fill, COLORS.out.stroke);

    arrowDown(gs, CX, y, hBottom, COLORS.update.stroke);

    const rowY = hBottom + BOX_TO_ROW;
    seqMatrix(gs, CX, rowY, 'z_0', `[${nPatches}, ${dModel}]`, COLORS.out.fill, COLORS.out.stroke, 260, MAT_H);
    lbl(gs, CX, rowY - MAT_H / 2 - 16, 'Final Denoised Latent', { size: 12, color: COLORS.out.stroke, weight: '700' });

    shapeEq(gs, CX, rowY + MAT_H / 2 + 28,
      `z_0 [${nPatches}, ${dModel}] — sent to VAE decoder to produce the output image`, COLORS.out.stroke);

    stepsMeta.push(makeStep(stepId, 'Output', 'Output: Denoised Latent',
      `z_0 [${nPatches}, ${dModel}]`,
      'After the final timestep, the latent z_0 is decoded by the VAE to produce the generated image.',
      'step-output', COLORS.out.stroke, COLORS.out.fill,
      [`# Final denoised latent`,
       `image = vae_decoder(z_0)   # [3, H, W]`]));
    y = rowY + MAT_H / 2 + 28 + SHAPE_GAP;
  }

  // ── Footer ───────────────────────────────────────────────────────────────
  y += 32;
  const insightText = scheduler === 'ddpm'
    ? 'DDPM is the original stochastic sampler. It adds random noise at each step, so sampling the same prompt twice yields different images. More steps reduce artifacts but increase cost.'
    : scheduler === 'ddim'
    ? 'DDIM removes the per-step random noise, making sampling deterministic. It can also use fewer steps (e.g. 20-50) with little quality loss, which is why it is popular for fast inference.'
    : scheduler === 'euler'
    ? 'Euler is a simple first-order ODE solver. It is fast and works well for flow-matching models, but may need careful step-size tuning for high-quality results.'
    : 'DPM++ uses a second-order update rule with past noise estimates. It often gives higher-quality samples in 10-30 steps, trading slightly more memory for fewer function evaluations.';

  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, insightText, 'insight');
  y += 24;

  const perfText = `Each sampling step requires one forward pass of the denoising model. Total cost scales as O(steps × patches × d_model²). Fewer steps or faster schedulers (DDIM/Euler) reduce latency.`;
  y = drawExplanation(g as Sel, CX - (W - 160) / 2, y, W - 160, perfText, 'perf');
  y += 24;

  drawComponentLink(g as Sel, CX - (W - 160) / 2, y, (W - 160) / 2 - 8, 56, 'dit-architecture', 'DiT Architecture');
  drawComponentLink(g as Sel, CX + 8, y, (W - 160) / 2 - 8, 56, 'image-tokenizer', 'Image Tokenizer');
  y += 72;

  const codeTitle = `Diffusion Scheduler — ${scheduler.toUpperCase()} (PyTorch)`;
  const codeLines = scheduler === 'ddpm'
    ? [`# DDPM sampling`,
       `for t in reversed(range(${steps})):`,
       `    eps = model(z_t, t)                       # [${nPatches}, ${dModel}]`,
       `    alpha_t = schedule.alpha[t]`,
       `    alpha_bar_t = schedule.alpha_bar[t]`,
       `    beta_t = 1 - alpha_t`,
       `    mu = (z_t - beta_t/sqrt(1-alpha_bar_t)*eps) / sqrt(alpha_t)`,
       `    z_t = mu + sqrt(beta_t)*torch.randn_like(z_t)`]
    : scheduler === 'ddim'
    ? [`# DDIM sampling`,
       `for t in reversed(range(${steps})):`,
       `    eps = model(z_t, t)`,
       `    alpha_bar_t = schedule.alpha_bar[t]`,
       `    alpha_bar_t_1 = schedule.alpha_bar[t-1] if t > 0 else 1.0`,
       `    x0 = (z_t - sqrt(1-alpha_bar_t)*eps) / sqrt(alpha_bar_t)`,
       `    z_t = sqrt(alpha_bar_t_1)*x0 + sqrt(1-alpha_bar_t_1)*eps`]
    : scheduler === 'euler'
    ? [`# Euler sampler`,
       `for t in reversed(range(${steps})):`,
       `    eps = model(z_t, t)`,
       `    sigma_t = schedule.sigma[t]`,
       `    z_t = z_t - sigma_t * eps`]
    : [`# DPM++ 2M sampler`,
       `eps_prev = None`,
       `for t in reversed(range(${steps})):`,
       `    eps = model(z_t, t)`,
       `    if eps_prev is not None:`,
       `        z_t = z_t + gamma_1*eps + gamma_2*eps_prev`,
       `    eps_prev = eps`];

  drawCodeAnnotation(g as Sel, CX - (W - 160) / 2, y, W - 160, codeTitle,
    [`${schedulerLabel[scheduler]} — ${nPatches} patches, d=${dModel}, ${steps} steps`], codeLines);

  return { width: W, height: y + 160, steps: stepsMeta };
}
